package palindrome

import (
	"errors"
	"fmt"
	"strings"
)

// Product holds a palindromic product and all of its factorizations
// within the given range.
type Product struct {
	Product       int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromic products of two
// numbers within the inclusive range [fmin, fmax], along with all of
// the factor pairs for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	minFound, maxFound := false, false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			p := i * j
			if !isPalindrome(p) {
				continue
			}
			if !minFound || p < min.Product {
				min = Product{p, [][2]int{{i, j}}}
				minFound = true
			} else if p == min.Product {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			if !maxFound || p > max.Product {
				max = Product{p, [][2]int{{i, j}}}
				maxFound = true
			} else if p == max.Product {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if !minFound {
		return Product{}, Product{}, errors.New("no palindromes")
	}
	return min, max, nil
}

// isPalindrome reports whether n's decimal digits read the same
// forwards and backwards.
func isPalindrome(n int) bool {
	s := fmt.Sprint(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

var _ = strings.HasPrefix // keep strings import if unused? no-op

